import numpy as np


def relu(x):
    return np.maximum(0, x)


def conv2d(image, kernel):
    kh, kw = kernel.shape
    out = np.zeros((image.shape[0] - kh + 1, image.shape[1] - kw + 1))
    for i in range(out.shape[0]):
        for j in range(out.shape[1]):
            out[i, j] = np.sum(image[i:i + kh, j:j + kw] * kernel)
    return out


def max_pool(x, size=2):
    h, w = x.shape[0] // size, x.shape[1] // size
    return x[:h * size, :w * size].reshape(h, size, w, size).max(axis=(1, 3))


def cnn_forward(image, k1, k2, W, b):
    shapes = [("input", image.shape)]
    x = relu(conv2d(image, k1)); shapes.append(("conv1", x.shape))
    x = max_pool(x); shapes.append(("pool1", x.shape))
    x = relu(conv2d(x, k2)); shapes.append(("conv2", x.shape))
    x = max_pool(x); shapes.append(("pool2", x.shape))
    x = x.flatten(); shapes.append(("flatten", x.shape))
    x = x @ W + b; shapes.append(("linear", x.shape))
    return x, shapes


rng = np.random.default_rng(0)
image = rng.random((28, 28))                    # an MNIST-sized grayscale image
k1, k2 = rng.standard_normal((3, 3)), rng.standard_normal((3, 3))
W, b = rng.standard_normal((25, 10)) * 0.1, np.zeros(10)
result = cnn_forward(image, k1, k2, W, b)
if result is None:
    print("cnn_forward() returned None")
else:
    logits, shapes = result
    for name, shape in shapes:
        print(f"{name:>8}: {shape}")
